{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C21"],
      "claim": "Faropenem, a penem sharing the hydroxyethyl-substituted bicyclic core, has 72-84% oral bioavailability in children, supporting high F for the query's penem-like scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Cefuroxime axetil, which shares the acetyloxymethyl ester and carbamoyloxymethyl prodrug motif, has a mean absolute oral bioavailability of 64% in humans, supporting F≥20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "DZ-2640, an oral beta-lactam ester prodrug, has bioavailability estimated at least greater than 30% in humans, supporting the prodrug approach for this scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Pivampicillin, an acyloxymethyl ester prodrug of a beta-lactam, achieves 82% absolute oral bioavailability in humans, demonstrating that this prodrug strategy can yield high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Cefditoren, a cephalosporin ester prodrug, has only about 14% fasting absolute bioavailability, a contradictory example showing that ester prodrugs can fall below 20%.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C18"],
      "claim": "Doripenem has low oral bioavailability and is given intravenously, but it lacks the ester prodrug modification and is less transferable to the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a beta-lactam ester prodrug with a penem-like core. The closest experimental analogues—faropenem (72-84% F), cefuroxime axetil (30-64% F), and pivampicillin (50-89% F)—show that this prodrug class can achieve F≥20%. The low-F examples are less transferable or lack the prodrug ester, so the experimental evidence outweighs the unfavorable physicochemical prior.",
  "evidence_gaps": [
    "No direct experimental bioavailability measurement exists for the exact query molecule.",
    "The gastrointestinal stability and hydrolysis rate of the acetyloxymethyl ester in humans are not directly evidenced.",
    "The structural reasons why cefditoren has lower F than cefuroxime axetil are not fully quantified, creating uncertainty for ester prodrugs in this class.",
    "A predicted F of 2% for cefuroxime parent is non-experimental and not applicable to the ester prodrug form."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

